      "strategi taktis dan pengorbanan harta benda agar fasilitas vital tidak dimanfaatkan Sekutu maupun NICA",
      "perintah langsung dari pihak Sekutu untuk mengosongkan sekaligus menghancurkan seluruh kota di Jawa Barat",
      "konflik internal antarlaskar perjuangan dalam memperebutkan penguasaan gedung pemerintahan di kota Bandung",
