      "Langsung memperbaiki rumus tabel tersebut secara mandiri tanpa memberitahu ketua tim maupun rekan lain yang menggunakan data tersebut.",
      "Menutupi kekhilafan diri dengan berdalih bahwa kesalahan kalkulasi pada tabel murni terjadi akibat malafungsi sistem perangkat lunak.",
