      "Mengusulkan pengadaan lisensi resmi kepada bagian TI sembari menunda pengerjaan infografis hingga aplikasi tersedia.",
      "Menggunakan aplikasi desain daring gratisan yang legal namun membatasi detail desain agar sesuai fitur dasar tersedia.",
      "Mengunduh aplikasi bajakan lain dari situs forum agar lebih aman dan menginstalnya secara diam-diam di luar jam kerja."
