      "Memilih lokasi pembangunan berdasarkan perkiraan pengalaman lapangan semata tanpa mengacu pada tabel data angka kesakitan.",
      "Menyusun ringkasan tabel agregat per kecamatan memakai perangkat pengolah angka agar pimpinan lebih mudah membandingkannya."
