      "Menolak terprovokasi, mengingatkan di grup bahaya hasutan pelanggar hukum, lalu melaporkan akun/konten ke kanal aduan resmi.",
      "Memilih keluar dari grup alumni tanpa berkata apa-apa agar tidak ikut terseret dalam perdebatan konten ujaran kebencian.",
      "Menghubungi admin grup secara pribadi untuk meminta penghapusan pesan hasutan tersebut dan menasihati pengirim secara santun."
