    id: "TIU-041", subtes: "TIU", topik: "Verbal",
    soal: "Lawan kata (antonim) dari kata \"PROGRESIF\" dalam kalimat \"Pemerintah daerah menerapkan kebijakan pajak progresif dan reformasi birokrasi yang berkelanjutan\" adalah ....",
