    soal: "Perhatikan kalimat tidak efektif berikut:\n\"Bagi seluruh pelamar CPNS yang telah lulus tahap administrasi harap segera mencetak kartu ujian di portal resmi agar supaya tidak tertinggal jadwal.\"\n\nPerbaikan kalimat tersebut agar menjadi kalimat EFEKTIF sesuai kaidah tata bahasa Indonesia baku adalah ....",
