      "Seluruh pejabat fungsional instansi merupakan peserta yang menghadiri rapat hari ini.",
      "Tidak ada peserta rapat hari ini yang termasuk pejabat fungsional penyusun angka kredit.",
      "Sebagian tenaga honorer instansi tetap diwajibkan menyusun angka kredit setiap tahunnya.",
