      "Membangun kolaborasi resmi bersama LSM dan akademisi kampus setempat agar program pemberdayaan lebih tepat sasaran dan terpadu.",
      "Menyalin dan memanfaatkan seluruh data kajian milik LSM tanpa meminta izin resmi serta mengabaikan kontribusi peneliti di lapangan.",
