      "Berdialog santun dengan tokoh adat untuk menyelaraskan waktu sosialisasi setelah upacara adat dan menghormati tata krama setempat.",
      "Memutuskan membatalkan seluruh agenda sosialisasi program di wilayah tersebut tanpa berupaya mencari jalan keluar maupun melapor ke pimpinan.",
      "Menilai tradisi adat tersebut sebagai penghambat kemajuan daerah dan menyatakannya secara terang-terangan di hadapan forum warga setempat.",
      "Bersikeras melaksanakan sosialisasi dinas secara sepihak dan memaksakan kehadiran warga di tengah rangkaian prosesi sakral yang sedang berlangsung."
