      "Menggandeng penerjemah lokal tepercaya untuk menerangkan tujuan pendataan secara ramah demi kepentingan warga setempat.",
      "Membuat berita acara penolakan sepihak dan mendesak perwakilan warga menandatanganinya agar petugas terbebas dari beban tugas survei.",
